}

.round {
    border-radius: 50%;
}

@keyframes sk-scaleout {
    0% {
        -webkit-transform: scale(0);
    }

    100% {
        -webkit-transform: scale(1);
        opacity: 0;
    }
}

@keyframes sk-scaleout {
    0% {
        -webkit-transform: scale(0);
        transform: scale(0);
    }

    100% {
        -webkit-transform: scale(1);
        transform: scale(1);
        opacity: 0;
    }
}


.spinner {


    position: fixed;
    top: 50%;
    left: 50%;
    display: flex;
    align-items: center;
    justify-content: center;


    -ms-transform: translateX(-50%) translateY(-50%);
    -webkit-transform: translate(-50%, -50%);
    transform: translate(-50%, -50%);


}

.blink {

    position: absolute;
    width: 250px;
    height: 250px;

    animation: blink 1.5s infinite ease;





}

@keyframes blink {
    0% {
        opacity: 0;
        -webkit-transform: scale(0);
        transform: scale(0);
    }

    100% {
        opacity: 1;
        -webkit-transform: scale(1);
        transform: scale(1);

    }
}

.block-icons {
    background: #282b32;


}

.block-icons {
    background: #282b32;
    box-shadow: 0px 0px 24px rgba(0, 0, 0, 0.15);
    min-height: 20px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    /* align-items: center; */
    padding: 20px;
    position: relative;
    transition: 0.3s ease;
    padding: 5px;
    max-height: 130px;
    padding-bottom: 10px;
}

.block-icons img {
    margin-bottom: 0px;
    transition: 0.3s ease;
    max-height: 50px;
    max-width: 100%;
}

.block-icons:hover {
    background-color: #1da912;
}



.block-icons:hover:before {
    border-color: #fff;
}



.block-icons h6 {
    position: relative;
    letter-spacing: 0.1em;
    padding-bottom: 5px;
    transition: 0.3s ease;
    text-align: center;
    padding-top: 10px;
}

.block-icons:hover h6 {
    padding-top: 10px;
}

.block-icons h6:before {
    content: "";
    position: absolute;
    top: 0;
    left: 50%;
    transform: translate(-50%, 0);
    width: 50px;
    height: 2px;

    background-color: #1da912;
    transition: 0.3s ease;
}

.block-icons:hover h6:before {
    background-color: #292929;
}

.block-icons:before {
    content: "";
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: calc(100% - 10px);
    height: calc(100% - 10px);
    border: 2px solid #1da912;
    transition: 0.4s ease;
    box-shadow: 0px 0px 5px rgb(0 0 0 / 10%);
    pointer-events: none;
}

.block-icons:hover:before {
    border: 2px solid #fff;
}


