/*-------------------- DEFAULT STYLES --------------------*/

.carousel-indicators {
    position: absolute;
    right: 0;
    bottom: 0;
    left: 0;
    z-index: 2;
    display: flex;
    justify-content: center;
    padding: 0;
    list-style: none;
}

.carousel .carousel-indicators button {
    background-color: none;
    border: solid green 2px;
    border-radius: 100%;
    width: 10px;
    height: 10px;
    /*  padding: 2px;
  */
    margin-left: 2px;
}

html {
    -webkit-text-size-adjust: 100%;
    -ms-text-size-adjust: 100%;
}

body {
    color: #282b32;
    font-size: 17px;
    line-height: 1.47em;
    font-family: "Mulish", serif;
    min-width: 320px;
    background: #efefef;
    background-position: top center;
    background-size: cover;
    background-repeat: no-repeat;
    min-height: 100vh;
    margin: 0px;
    padding-right: 0px;
    /*  border: solid blue 2px;*/
}

table.center {
    margin-left: auto;
    margin-right: auto;
}

#customers {
    font-family: "Mulish", serif;
    border-collapse: collapse;
    margin-left: auto;
    margin-right: auto;
    width: 50%;
}

#customers td,
#customers th {
    border: 1px solid #ddd;
    padding: 8px;
}

#customers tr:nth-child(even) {
    background-color: #f2f2f2;
}

#customers tr:hover {
    background-color: #ddd;
}

#customers th {
    padding-top: 12px;
    padding-bottom: 12px;
    text-align: left;
    background-color: #04AA6D;
    color: white;
}

* {
    box-sizing: border-box;
    outline: none !important;
}

*:before,
*:after {
    box-sizing: border-box;
}

.hide {
    display: none;
}

.galleryImg-margin {
    margin: 10px 0px;
}

b,
strong {
    font-weight: bold;
}

button,
input[type="button"],
input[type="submit"] {
    transition: 0.3s ease;
    color: #fff;
    font-family: "Mulish", sans-serif;
}

button[disabled],
html input[disabled] {
    cursor: default;
}

button::-moz-focus-inner,
input::-moz-focus-inner {
    padding: 0;
    border: 0;
}

input[type="text"],
input[type="tel"],
input[type="email"],
input[type="search"],
input[type="password"],
input[type="url"],
select,
textarea {
    display: block;
    width: 100%;
    height: 46px;
    padding: 8px 10px 10px 42px;
    font-family: "Mulish", sans-serif;
    font-weight: 700;
    font-size: 14px;
    line-height: 18px;
    color: #fff;
    background-color: transparent;
    font-weight: 500;
    transition: 0.3s ease;
}

input[type="search"],
input[type="text"],
input[type="tel"],
input[type="email"],
input[type="search"],
input[type="password"],
textarea {
    border: 1px solid #5f5f5f;
}

textarea {
    resize: none;
    height: 184px;
    padding-top: 16px;
}

input[type="search"]:focus,
input[type="text"]:focus,
input[type="tel"]:focus,
input[type="email"]:focus,
input[type="search"]:focus,
input[type="password"]:focus,
