/*-------------------- HOME 1 MAIN --------------------*/
.main-slider-cover {
    position: relative;
    overflow: hidden;
}

.main-slider-for .slider-track {
    transition: all 1s cubic-bezier(0.7, 0, 0.3, 1);
}

.main-slide-for {
    height: 900px;
    position: relative;
    overflow: hidden;
}

.main-slide-for img,
.main-slide-for video {
    display: block;
    position: absolute;
    min-height: 100%;
    min-width: 100%;
    top: 0;
    left: 0;
    pointer-events: none;
}

.main-slide-for img {
    object-fit: cover;
    height: 100%;
    max-width: 100%;
    width: 100%;
    transition: all 1s cubic-bezier(0.7, 0, 0.3, 1);
    transform: scale(1.2) rotate(5deg);
}

.main-slide-for.slick-active img {
    transform: scale(1) rotate(0);
}

.main-slider-nav {
    max-width: 754px;
    position: absolute;
    bottom: 55px;
    right: 0;
    z-index: 1;
    margin-right: -10px;
    padding-bottom: 53px;
}

.main-slide-nav {
    padding: 0 10px;
    transition: 0.3s ease;
    position: relative;
}

.main-slide-nav .img-cover {
    position: relative;
    border-bottom: 5px solid #000;
    transition: 0.3s ease;
}

.main-slide-nav .img-cover:before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-color: #000;
    opacity: 0.5;
    z-index: 1;
    transition: 0.3s ease;
}

.main-slide-nav img {
    height: 152px;
    object-fit: cover;
    width: 100%;
    display: block;
    transition: 0.3s ease;
    box-shadow: 0px 4px 4px rgba(0, 0, 0, 0.25);
}

.main-slide-nav.slick-current .img-cover:before,
.main-slide-nav:hover .img-cover:before {
    opacity: 0;
}

.main-slide-nav:hover .img-cover {
    border-color: #1da912;
}

.main-slide-nav.slick-current,
.main-slide-nav:hover img {
    box-shadow: none;
}

.main-slide-nav span {
    position: absolute;
    font-size: 36px;
    font-weight: 700;
    bottom: 20px;
    left: 0;
    opacity: 0.3;
    z-index: 2;
    transition: 0.3s ease;
    color: #fff;
}

.main-slide-nav.slick-current span,
.main-slide-nav:hover span {
    opacity: 1;
    text-shadow: 0px 4px 4px rgba(0, 0, 0, 0.25);
}

.main-slider-nav .slick-arrow {
    position: absolute;
    width: 115px;
    height: 38px;
    bottom: 0;
    left: 10px;
    background-color: #131213;
    display: block;
    text-align: center;
    transition: 0.3s ease;
}

.main-slider-nav .slick-arrow:hover {
    background-color: #1da912;
}

.main-slider-nav .slick-arrow-next.slick-arrow {
    left: 130px;
}

.main-slider-nav .slick-arrow i {
    color: #fff;
    margin: auto;
    line-height: 38px;
}

.main-slide-for .container {
    height: 100%;
    z-index: 1;
    display: flex;
    align-items: flex-end;
    padding-bottom: 55px;
    z-index: 1;
}

