/*----------------------- TO-TOP -----------------------*/
.to-top {
    position: fixed;
    bottom: 30px;
    right: 20px;
    opacity: 0;
    pointer-events: none;
    z-index: 22;
    transition: 0.3s ease-in-out;
}

.to-top.active {
    opacity: 1;
    pointer-events: auto;
}

.to-top span {
    width: 60px;
    height: 60px;
    border-radius: 50%;
    border: 2px solid #565656;
    border-right: none;
    border-top: none;
    display: block;
    position: relative;
    animation: rotate-to-top 20s linear 0s infinite normal;
    transition: 0.3s ease;
}

.to-top:hover span {
    border-color: #1da912;
}

@keyframes rotate-to-top {
    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }
}

.to-top img {
    width: 20px;
    position: absolute;
    top: 0;
    right: 0;
    animation: to-top-drone 5s linear 0s infinite normal;
}

@keyframes to-top-drone {
    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(-360deg);
    }
}

.to-top i {
    z-index: 1;
    position: absolute;
    top: 48%;
    left: 50%;
    transform: translate(-50%, -50%);
    color: #565656;
    font-size: 20px;
    transition: 0.3s ease;
}

.to-top:hover i {
    color: #1da912;
}

